import{_ as a,o as t,c as n,a2 as o}from"./chunks/framework.BWuWLRhz.js";const m=JSON.parse('{"title":"Acciones y vista previa instantánea","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. Menú de acciones en detalle","slug":"_1-menu-de-acciones-en-detalle","link":"#_1-menu-de-acciones-en-detalle","children":[{"level":3,"title":"Tabla de acciones principales integradas","slug":"tabla-de-acciones-principales-integradas","link":"#tabla-de-acciones-principales-integradas","children":[]},{"level":3,"title":"Interacción y filtrado en el Menú de acciones","slug":"interaccion-y-filtrado-en-el-menu-de-acciones","link":"#interaccion-y-filtrado-en-el-menu-de-acciones","children":[]}]},{"level":2,"title":"2. Características de la lista de la Ventana principal","slug":"_2-caracteristicas-de-la-lista-de-la-ventana-principal","link":"#_2-caracteristicas-de-la-lista-de-la-ventana-principal","children":[]},{"level":2,"title":"3. Vista previa instantánea con QuickLook","slug":"_3-vista-previa-instantanea-con-quicklook","link":"#_3-vista-previa-instantanea-con-quicklook","children":[{"level":3,"title":"La vista previa no tiene teclado","slug":"la-vista-previa-no-tiene-teclado","link":"#la-vista-previa-no-tiene-teclado","children":[]},{"level":3,"title":"Formatos admitidos y funciones avanzadas","slug":"formatos-admitidos-y-funciones-avanzadas","link":"#formatos-admitidos-y-funciones-avanzadas","children":[]},{"level":3,"title":"Ajuste de pantalla y gestión de ventanas emergentes","slug":"ajuste-de-pantalla-y-gestion-de-ventanas-emergentes","link":"#ajuste-de-pantalla-y-gestion-de-ventanas-emergentes","children":[]}]},{"level":2,"title":"4. Paneles interactivos y texto enriquecido con plugins","slug":"_4-paneles-interactivos-y-texto-enriquecido-con-plugins","link":"#_4-paneles-interactivos-y-texto-enriquecido-con-plugins","children":[]},{"level":2,"title":"5. Puente con QuickLook de terceros (Opcional)","slug":"_5-puente-con-quicklook-de-terceros-opcional","link":"#_5-puente-con-quicklook-de-terceros-opcional","children":[]},{"level":2,"title":"6. Liberar la ocupación de un archivo","slug":"_6-liberar-la-ocupacion-de-un-archivo","link":"#_6-liberar-la-ocupacion-de-un-archivo","children":[]},{"level":2,"title":"7. Añadir a Favoritos","slug":"_7-anadir-a-favoritos","link":"#_7-anadir-a-favoritos","children":[]},{"level":2,"title":"8. Cambiar nombre","slug":"_8-cambiar-nombre","link":"#_8-cambiar-nombre","children":[]}],"relativePath":"es-ES/user-guide/actions-and-preview.md","filePath":"es-ES/user-guide/actions-and-preview.md","lastUpdated":1791112464000}'),i={name:"es-ES/user-guide/actions-and-preview.md"};function l(r,e,s,c,d,u){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="acciones-y-vista-previa-instantanea" tabindex="-1">Acciones y vista previa instantánea <a class="header-anchor" href="#acciones-y-vista-previa-instantanea" aria-label="Permalink to &quot;Acciones y vista previa instantánea&quot;">​</a></h1><p>Lertaro localiza archivos e integra un sistema de acciones contextuales y un panel de vista previa instantánea, lo que te permite inspeccionar, gestionar y abrir archivos sin cambiar al Explorador de archivos.</p><h2 id="_1-menu-de-acciones-en-detalle" tabindex="-1">1. Menú de acciones en detalle <a class="header-anchor" href="#_1-menu-de-acciones-en-detalle" aria-label="Permalink to &quot;1. Menú de acciones en detalle&quot;">​</a></h2><p>En la Ventana rápida, pulsa <code>Ctrl+O</code> o la flecha derecha <code>→</code> sobre el resultado resaltado para desplegar el menú de acciones contextuales; <code>→</code> solo cuando el cursor ya está al final de la consulta, de modo que nunca roba el movimiento del cursor mientras editas el texto más atrás. Las mismas teclas funcionan en la tarjeta incrustada <strong>fuera</strong> de los diálogos de archivos; una tarjeta acoplada en un diálogo Abrir/Guardar/Examinar no tiene menú de acciones. En la Ventana principal ninguna de las dos teclas está asignada: haz clic derecho en un resultado, o pulsa <code>Apps</code> (<code>Shift+F10</code>), para abrir ahí el mismo menú.</p><p>No todas las filas tienen menú. No está disponible en la fila <strong>Ver más</strong>, en los resultados aportados por plugins, en los favoritos que son enlaces web, en los resultados instantáneos que ningún proveedor reclama, en las aplicaciones fuera de la Ventana rápida ni en ningún diálogo de archivos; en esas filas las teclas del menú no hacen nada en lugar de abrir un panel vacío.</p><h3 id="tabla-de-acciones-principales-integradas" tabindex="-1">Tabla de acciones principales integradas <a class="header-anchor" href="#tabla-de-acciones-principales-integradas" aria-label="Permalink to &quot;Tabla de acciones principales integradas&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Acción</th><th style="text-align:left;">Atajo predeterminado</th><th style="text-align:left;">Descripción</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Abrir</strong></td><td style="text-align:left;"><code>Enter</code></td><td style="text-align:left;">Abre el elemento seleccionado o inicia la aplicación con el programa predeterminado del sistema. En la Ventana principal, <code>Enter</code> actúa sobre <strong>todas</strong> las filas seleccionadas; el doble clic abre solo la fila sobre la que haces doble clic.</td></tr><tr><td style="text-align:left;"><strong>Mostrar en Explorador</strong></td><td style="text-align:left;"><code>Ctrl+Enter</code></td><td style="text-align:left;">Abre la carpeta contenedora y selecciona el archivo en el Explorador de Windows.</td></tr><tr><td style="text-align:left;"><strong>Ejecutar como administrador</strong></td><td style="text-align:left;"><code>Ctrl+Shift+Enter</code></td><td style="text-align:left;">Inicia la aplicación seleccionada con privilegios de administrador elevados.</td></tr><tr><td style="text-align:left;"><strong>Copiar ruta completa</strong></td><td style="text-align:left;"><code>Ctrl+Shift+C</code></td><td style="text-align:left;">Copia la ruta absoluta (p. ej. <code>D:\\Projects\\app.exe</code>) al portapapeles.</td></tr><tr><td style="text-align:left;"><strong>Copiar nombre</strong></td><td style="text-align:left;"><code>Shift+C</code></td><td style="text-align:left;">Copia al portapapeles los nombres de los archivos o carpetas seleccionados, sin sus rutas.</td></tr><tr><td style="text-align:left;"><strong>Copiar archivo</strong></td><td style="text-align:left;"><code>Ctrl+C</code></td><td style="text-align:left;">Coloca el archivo en el portapapeles, listo para pegarlo en el Explorador o cualquier carpeta.</td></tr><tr><td style="text-align:left;"><strong>Cortar / Copiar archivo</strong></td><td style="text-align:left;"><code>Ctrl+X</code> / <code>Ctrl+C</code></td><td style="text-align:left;">Coloca el archivo en el portapapeles, listo para pegarlo en el Explorador o cualquier carpeta. Si hay texto seleccionado en el cuadro de búsqueda, estas teclas siguen siendo órdenes sobre el texto.</td></tr><tr><td style="text-align:left;"><strong>Pegar en esta carpeta</strong></td><td style="text-align:left;"><code>Ctrl+V</code></td><td style="text-align:left;">Cuando una carpeta está resaltada, pega los archivos del portapapeles directamente en ese directorio; cuando un archivo está resaltado, pega en su carpeta contenedora. Necesita una lista real de archivos en el portapapeles, así que pegar texto en la consulta no se ve afectado.</td></tr><tr><td style="text-align:left;"><strong>Eliminar (Papelera de reciclaje)</strong></td><td style="text-align:left;"><code>Delete</code></td><td style="text-align:left;">Mueve el archivo o carpeta seleccionado a la Papelera de reciclaje de Windows de forma segura. Una tecla aislada solo llega a la acción cuando el cursor ya está al final de la consulta, y después llega la confirmación nativa de la Papelera.</td></tr><tr><td style="text-align:left;"><strong>Eliminación permanente</strong></td><td style="text-align:left;"><code>Shift+Delete</code></td><td style="text-align:left;">Elimina permanentemente el elemento (aviso nativo de &quot;¿eliminar definitivamente?&quot;; después de eso no se puede recuperar).</td></tr><tr><td style="text-align:left;"><strong>Cambiar nombre</strong></td><td style="text-align:left;">—</td><td style="text-align:left;">Cambia el nombre de un único archivo o carpeta existente mediante Windows Shell. El diálogo selecciona de antemano la parte del nombre para facilitar su sustitución.</td></tr><tr><td style="text-align:left;"><strong>Menú contextual de Windows</strong></td><td style="text-align:left;">—</td><td style="text-align:left;">Despliega el menú contextual nativo completo de Windows Explorer (incluyendo opciones de terceros y &quot;Enviar a&quot;).</td></tr></tbody></table><h3 id="interaccion-y-filtrado-en-el-menu-de-acciones" tabindex="-1">Interacción y filtrado en el Menú de acciones <a class="header-anchor" href="#interaccion-y-filtrado-en-el-menu-de-acciones" aria-label="Permalink to &quot;Interacción y filtrado en el Menú de acciones&quot;">​</a></h3><ul><li><strong>Escribir para filtrar</strong>: Al abrir el menú de acciones, escribe directamente para filtrar por nombre (p. ej., teclear <code>copy</code> reduce la lista a las acciones de copiado). El cuadro de filtro se queda con el teclado, así que navegar hacia otro sitio nunca toca tu consulta original.</li><li><strong>Letra mnemotécnica</strong>: Cada acción puede mostrar una letra resaltada. Pulsarla <strong>ejecuta la acción de inmediato</strong>, no se limita a resaltarla, pero solo mientras el cuadro de filtro esté aún vacío, de modo que nunca te roba la primera letra que tecleas para filtrar.</li><li><strong>Cuadro de búsqueda independiente</strong>: El menú de acciones tiene su propio cuadro de búsqueda, que recibe el foco automáticamente al abrirse. Filtrar acciones no cambia la consulta principal. Al cambiar de nivel se borra el filtro de acciones y el cuadro del nuevo nivel recibe el foco.</li><li><strong>Panel de acciones flotante</strong>: En la Ventana rápida, el panel de Inicio rápido y la Ventana principal, las acciones aparecen en un panel flotante anclado al elemento activo. El panel de Inicio rápido se amplía temporalmente a la altura de trabajo completa de la lista de acciones y vuelve a su tamaño compacto al cerrarse.</li><li><strong>Navegación jerárquica</strong>: En elementos con submenús (como &quot;Enviar a&quot;), pulsa <code>→</code>, <code>Tab</code> o <code>Enter</code> para entrar; pulsa <code>←</code> o <code>Backspace</code> (con el filtro vacío) para regresar al nivel superior. En un menú anidado, <code>Escape</code> o el clic derecho regresan al nivel superior; en la raíz cierran el menú de acciones.</li><li><strong>Las teclas de navegación siguen funcionando</strong>: Los atajos configurados de elemento siguiente/anterior (<code>Ctrl+N</code> / <code>Ctrl+P</code> por defecto) también mueven el resaltado dentro de la lista de acciones, dando la vuelta al primer y último elemento y saltando separadores, encabezados y acciones deshabilitadas. <code>Tab</code> entra en un submenú solo si no la has asignado a una de esas teclas.</li><li><strong>Cerrar al hacer clic fuera</strong>: Al hacer clic fuera de un panel flotante, este se cierra. Si el anfitrión lo permite, hacer clic derecho en otro resultado mientras el panel está abierto reemplaza el objetivo en el mismo lugar.</li><li><strong>Atajos de acciones</strong>: Mientras el panel tiene el foco puedes usar los atajos definidos por los proveedores. Al ejecutarlos se cierra el panel flotante, pero la Ventana principal o el panel de Inicio rápido permanecen abiertos.</li></ul><h2 id="_2-caracteristicas-de-la-lista-de-la-ventana-principal" tabindex="-1">2. Características de la lista de la Ventana principal <a class="header-anchor" href="#_2-caracteristicas-de-la-lista-de-la-ventana-principal" aria-label="Permalink to &quot;2. Características de la lista de la Ventana principal&quot;">​</a></h2><p>La Ventana principal de búsqueda (<code>Ctrl+F</code>) está diseñada para la gestión masiva de archivos y la exploración profunda:</p><ul><li><strong>Doble clic en la columna Ruta</strong>: Hacer doble clic en la columna <strong>Nombre</strong> abre el archivo; hacer doble clic en la columna <strong>Ruta</strong> abre directamente la carpeta que lo contiene. Doble clic significa solo el botón <em>izquierdo</em>; un doble clic en el encabezado de una columna no hace nada, y maximizar o restaurar se hace con un doble clic en la banda superior no interpactable de la ventana.</li><li><strong>Selección múltiple</strong>: La cuadrícula es una lista normal de Windows: <code>Ctrl</code>+clic añade o quita filas, <code>Shift</code>+clic toma un rango, y <code>Enter</code> actúa entonces sobre <strong>todas</strong> las filas seleccionadas a la vez, mientras que el doble clic abre solo la fila sobre la que haces doble clic. El clic derecho en una fila que ya forma parte de una selección conserva toda la selección en lugar de reducirla a esa única fila.</li><li><strong>Carga continua de resultados en streaming</strong>: Al escanear millones de elementos, los resultados se van añadiendo a la lista en tiempo real sin tener que esperar a que finalice el escaneo completo. Puedes interactuar con las filas al instante, y añadir filas nuevas conserva tu selección y tu posición de desplazamiento; un conjunto de resultados realmente nuevo empieza de nuevo desde arriba.</li><li><strong>Navegación en bucle</strong>: Pulsar <code>↑</code> en la primera fila salta al último elemento; pulsar <code>↓</code> en la última fila vuelve al primero. El mismo bucle se aplica en la Ventana rápida y en la tarjeta incrustada: pulsar <code>↑</code> sin nada seleccionado todavía cae en la última fila, y <code>↓</code> en la primera. Solo el Panel rápido recorre sus grupos como una lista continua <strong>sin</strong> dar la vuelta.</li><li><strong>Desplazamiento horizontal</strong>: <code>Shift</code> + rueda del ratón sobre la cuadrícula desplaza tres columnas por clic de rueda, que es como se alcanzan las columnas más lejanas en una ventana estrecha.</li><li><strong>Arrastrar archivos hacia fuera</strong>: Cualquier fila puede arrastrarse directamente al Explorador, a un diálogo o a una ventana de chat como una auténtica suelta de archivos; con una selección múltiple, arrastrar uno de sus miembros arrastra <strong>todos</strong>. Soltar fuera de Lertaro oculta la ventana, y el cierre se retiene mientras hay un arrastre en curso para que el cursor de arrastre no quede clavado.</li><li><strong>Resumen de selección</strong>: Al seleccionar varias filas, la barra de estado muestra el número de elementos seleccionados junto al total de resultados.</li><li><strong>Vistas previas al pasar el ratón</strong>: Mover el puntero sobre una fila reorienta un panel de vista previa ya abierto sin cambiar la selección, así que puedes ir probando candidatos y pulsar <code>Enter</code> en la fila donde te has quedado.</li><li><strong>Arrastre y memoria de tamaño</strong>: Arrastra la barra superior para reubicar la ventana; las dimensiones ajustadas manualmente se recuerdan automáticamente entre sesiones.</li></ul><h2 id="_3-vista-previa-instantanea-con-quicklook" tabindex="-1">3. Vista previa instantánea con QuickLook <a class="header-anchor" href="#_3-vista-previa-instantanea-con-quicklook" aria-label="Permalink to &quot;3. Vista previa instantánea con QuickLook&quot;">​</a></h2><p>Pulsa <code>Alt+P</code> sobre un resultado previsualizable para abrir el panel lateral de vista previa acoplado junto a la ventana de búsqueda, o haz <strong>clic central en la fila</strong>, que alterna ese mismo panel. Ninguno de los dos gestos está disponible en la ventana incrustada; el Panel rápido sí admite ambos.</p><h3 id="la-vista-previa-no-tiene-teclado" tabindex="-1">La vista previa no tiene teclado <a class="header-anchor" href="#la-vista-previa-no-tiene-teclado" aria-label="Permalink to &quot;La vista previa no tiene teclado&quot;">​</a></h3><p>El panel es deliberadamente no activador: nunca le quita el foco a la ventana de búsqueda, así que no hay dónde escribir y <code>Escape</code> no lo cierra. Alterna con <code>Alt+P</code>, u ocúltalo cerrando la ventana a la que está acoplado. Todos sus controles — la barra de reproducción multimedia, las barras de desplazamiento, las tarjetas de plugins — son solo de ratón, y el foco del teclado se queda exactamente donde estaba.</p><h3 id="formatos-admitidos-y-funciones-avanzadas" tabindex="-1">Formatos admitidos y funciones avanzadas <a class="header-anchor" href="#formatos-admitidos-y-funciones-avanzadas" aria-label="Permalink to &quot;Formatos admitidos y funciones avanzadas&quot;">​</a></h3><ul><li><strong>Imágenes</strong>: Renderizado escalado de imágenes JPG, PNG, GIF, BMP e ICO.</li><li><strong>Texto y código</strong>: Renderizado monoespaciado simple para TXT, Markdown, JSON, XML, YAML, C#, Python, JS, HTML, etc. (sin resaltado de sintaxis).</li><li><strong>Reproducción instantánea de audio y vídeo</strong>: Los archivos de vídeo (MP4, M4V, WMV, AVI, MOV, MPG/MPEG) y de audio (MP3, WAV, WMA, M4A, AAC) <strong>se reproducen automáticamente</strong> con una barra de control integrada que se adapta al tema (reproducir/pausa, barra de progreso, duración, silencio). Se detiene al instante al cambiar de elemento.</li><li><strong>Inspección de carpetas</strong>: Muestra hasta 30 elementos directos con iconos y tamaños, omitiendo archivos ocultos y del sistema.</li></ul><h3 id="ajuste-de-pantalla-y-gestion-de-ventanas-emergentes" tabindex="-1">Ajuste de pantalla y gestión de ventanas emergentes <a class="header-anchor" href="#ajuste-de-pantalla-y-gestion-de-ventanas-emergentes" aria-label="Permalink to &quot;Ajuste de pantalla y gestión de ventanas emergentes&quot;">​</a></h3><ul><li><strong>Ajuste automático de límites</strong>: Las dimensiones de la vista previa se pueden personalizar en <a href="./settings/general.html#_4-ventana-de-vista-previa"><strong>Configuración → General → Vista previa</strong></a>; Lertaro garantiza que nunca sobrepase el área visible del monitor.</li><li><strong>Lado de acoplamiento</strong>: El panel se acopla a la <strong>derecha</strong> de su ventana de búsqueda y pasa a la izquierda solo cuando a la derecha no cabe; no persigue el lado más espacioso, así que se queda quieto mientras desplazas una ventana ancha. Después sigue a su ventana propietaria cuando la mueves o la redimensionas.</li><li><strong>La memoria de tamaño dura la sesión</strong>: Arrastrar el asa de redimensionado o mover el panel se recuerda mientras la vista previa siga en juego, pero la próxima vez que la ventana de búsqueda se oculte o se cierre el panel vuelve al tamaño y al lado de acoplamiento configurados.</li><li><strong>Evitación de diálogos nativos</strong>: Al previsualizar documentos de Office protegidos con contraseña, Lertaro oculta temporalmente sus ventanas para que puedas introducir la contraseña sin bloqueos y las restaura después.</li><li><strong>Arrastrar desde la vista previa</strong>: La parte superior del panel sirve como origen de arrastre para llevar el archivo previsualizado directamente a editores, navegadores o chats. La barra inferior arrastra el propio panel.</li></ul><h2 id="_4-paneles-interactivos-y-texto-enriquecido-con-plugins" tabindex="-1">4. Paneles interactivos y texto enriquecido con plugins <a class="header-anchor" href="#_4-paneles-interactivos-y-texto-enriquecido-con-plugins" aria-label="Permalink to &quot;4. Paneles interactivos y texto enriquecido con plugins&quot;">​</a></h2><p>QuickLook también admite tarjetas interactivas proporcionadas por plugins:</p><ul><li><strong>Texto enriquecido adaptado al tema</strong>: Renderizado mediante WebView2 y controles nativos, adaptándose a temas oscuros y claros con tipografía de alto contraste y barras de desplazamiento sutiles.</li><li><strong>Tarjetas de plugins</strong>: Consultas de diccionarios MDict, pronóstico meteorológico, capturas web y depuración de APIs.</li></ul><h2 id="_5-puente-con-quicklook-de-terceros-opcional" tabindex="-1">5. Puente con QuickLook de terceros (Opcional) <a class="header-anchor" href="#_5-puente-con-quicklook-de-terceros-opcional" aria-label="Permalink to &quot;5. Puente con QuickLook de terceros (Opcional)&quot;">​</a></h2><p>Si utilizas la herramienta externa de código abierto <strong>QuickLook</strong> (<a href="https://github.com/QL-Win/QuickLook" target="_blank" rel="noreferrer">QL-Win/QuickLook en GitHub</a>), puedes activar el plugin <strong>Puente QuickLook</strong> en <a href="./settings/plugins.html"><strong>Configuración → Plugins</strong></a>.</p><ul><li><strong>Control de vista previa externa</strong>: Se conecta mediante canalizaciones con nombre locales para acoplar la ventana externa de QuickLook directamente junto a Lertaro.</li><li><strong>Alternativa automática</strong>: Si QuickLook externo no está ejecutándose, Lertaro recurre a su motor de vista previa integrado.</li></ul><h2 id="_6-liberar-la-ocupacion-de-un-archivo" tabindex="-1">6. Liberar la ocupación de un archivo <a class="header-anchor" href="#_6-liberar-la-ocupacion-de-un-archivo" aria-label="Permalink to &quot;6. Liberar la ocupación de un archivo&quot;">​</a></h2><p>El plugin oficial <strong>Liberar ocupación de archivos</strong> añade una acción disponible al seleccionar un único archivo existente. Muestra los procesos que lo están utilizando, sus PID y las rutas de sus ejecutables, y les solicita que liberen el archivo. La acción no está disponible para carpetas, archivos inexistentes ni selecciones múltiples; el botón de solicitud también se desactiva cuando no se detecta ningún proceso. El diálogo usa el tema del anfitrión, permanece sobre la ventana de búsqueda y queda oculto en Alt+Tab, además de incluir actualización manual.</p><h2 id="_7-anadir-a-favoritos" tabindex="-1">7. Añadir a Favoritos <a class="header-anchor" href="#_7-anadir-a-favoritos" aria-label="Permalink to &quot;7. Añadir a Favoritos&quot;">​</a></h2><p>CoreExtensions ofrece la acción <strong>Añadir a Favoritos</strong> para un único archivo o carpeta existente. Abre un diálogo con el tema del anfitrión para introducir el nombre visible y oculta la acción si la misma ruta ya está en Favoritos.</p><h2 id="_8-cambiar-nombre" tabindex="-1">8. Cambiar nombre <a class="header-anchor" href="#_8-cambiar-nombre" aria-label="Permalink to &quot;8. Cambiar nombre&quot;">​</a></h2><p>CoreExtensions ofrece la acción <strong>Cambiar nombre</strong> para un único archivo o carpeta existente. El diálogo con el tema del anfitrión muestra el nombre completo actual y selecciona de antemano la parte del nombre: en <code>report.pdf</code> solo se selecciona <code>report</code>, mientras que en carpetas y nombres sin extensión se selecciona todo el nombre. Pulsa <code>Enter</code> para confirmar o <code>Esc</code> para cancelar. Tras la confirmación, Windows Shell realiza el cambio de nombre.</p>',32)])])}const g=a(i,[["render",l]]);export{m as __pageData,g as default};
